'use strict';

// MODULES //

var tape = require( 'tape' );
var hasProp = require( '@stdlib/assert/has-property' );
var Fcn = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Fcn, 'function', 'main export is a function' );
	t.end();
});

tape( 'a function instance has a `prototype` property', function test( t ) {
	var f = new Fcn( 'x', 'y', 'return x + y' );
	t.strictEqual( hasProp( f, 'prototype' ), true, 'has property' );
	t.end();
});

tape( 'the property value is an object', function test( t ) {
	var f;

	f = new Fcn( 'x', 'y', 'return x + y' );
	t.strictEqual( typeof f.prototype, 'object', 'returns expected value' );
	t.end();
});

tape( 'named function declarations have a `prototype` property', function test( t ) {
	t.strictEqual( hasProp( add, 'prototype' ), true, 'has property' );
	t.strictEqual( typeof add.prototype, 'object', 'is an object' );
	t.end();

	function add( x, y ) {
		return x + y;
	}
});
